function find(id){
  const key=String(id),m=key.match(/^([LR])(\d+)$/);
  if(m){
    const listening=m[1]==='L',n=Number(m[2]),raw=listening?(typeof LS!=='undefined'?LS[n-1]:null):(typeof RW!=='undefined'?RW[n-1]:null);if(!raw)return null;
    return {...raw,id:key,sourceId:n,section:listening?'listening':'reading',group:raw.categoryKo||(listening?'듣기':'읽기'),instruction:raw.instruction||(listening?'다음을 듣고 가장 알맞은 것을 고르십시오.':'다음 글을 읽고 가장 알맞은 것을 고르십시오.'),choices:(raw.choices||[]).map(x=>String(x).replace(/^[①②③④]\s*/,''))}
  }
  return A.find(x=>x.id===Number(id))
}
function pool(k){return k==='listening'?L:k==='reading'?R:A}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function clock(s){s=Math.max(0,Math.floor(s));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}
