async function fileAudio(id,examLevel=Q?.examLevel||1){const n=String(id).padStart(3,'0'),folder=Number(examLevel)===2?'topik2':'topik1';for(const x of EXT){const u=`audio/${folder}/q${n}.${x}`;try{const r=await fetch(u,{method:'HEAD',cache:'no-store'});if(r.ok)return u}catch(e){}}return null}
function tts(txt){stopAudio();const lines=String(txt||'').replace(/^(여자|남자|안내|방송|여자\(안내\)|남자\(안내\)|여자\(설명\)|남자\(설명\)):\s*/gm,'').split(/\n+/).map(x=>x.trim()).filter(Boolean);let i=0,token=Date.now();window.__t1tts=token;const next=()=>{if(window.__t1tts!==token||i>=lines.length)return;const u=new SpeechSynthesisUtterance(lines[i++]);u.lang='ko-KR';u.rate=.91;u.pitch=1;try{const vs=speechSynthesis.getVoices().filter(v=>/^ko/i.test(v.lang));if(vs.length)u.voice=vs[(i-1)%vs.length]}catch(e){}u.onend=()=>setTimeout(next,230);u.onerror=()=>setTimeout(next,80);speechSynthesis.speak(u)};next()}
async function play(id){const q=find(id);if(!q)return;if(Q?.mode==='real'&&Q.played?.[id]){toast(T('실전 듣기는 한 번만 재생할 수 있습니다.','実戦の聞き取り音声は1回だけ再生できます。','Listening audio can be played only once in Exam Mode.','实战模式的听力音频只能播放一次。'));return}if(Q?.mode==='real'){Q.played[id]=1;saveQ();render()}stopAudio();const url=await fileAudio(q.sourceId||id,Q?.examLevel||1);if(!url)return tts(q.script);try{const a=new Audio(url+'?v='+Date.now());audio=a;try{const AC=window.AudioContext||window.webkitAudioContext;if(AC){ctx=ctx||new AC();if(ctx.state==='suspended')await ctx.resume();const s=ctx.createMediaElementSource(a),g=ctx.createGain(),c=ctx.createDynamicsCompressor();g.gain.value=1.3;c.threshold.value=-8;c.ratio.value=5;s.connect(g).connect(c).connect(ctx.destination)}}catch(e){}a.onended=()=>audio=null;await a.play()}catch(e){tts(q.script)}}
