function gameHeroSvg(){return `<svg class="tqGameHeroSvg" viewBox="0 0 180 195" aria-hidden="true"><defs><linearGradient id="tqCape" x1="0" x2="1"><stop stop-color="#ff485f"/><stop offset="1" stop-color="#d92750"/></linearGradient><linearGradient id="tqArmor" x1="0" x2="1"><stop stop-color="#2377db"/><stop offset="1" stop-color="#123f91"/></linearGradient></defs><path d="M52 102c-27 17-37 47-40 70 23-7 47-7 66 4l8-61z" fill="url(#tqCape)"/><path d="M67 151l-8 31h19l11-29zm41 0 8 31h19l-7-34z" fill="#263754"/><path d="M55 102c9-22 62-25 75 0l-5 61H67z" fill="url(#tqArmor)" stroke="#72b7ff" stroke-width="3"/><path d="M75 119h45v13H75z" fill="#ffc44e"/><circle cx="94" cy="67" r="43" fill="#ffd5ba" stroke="#17304d" stroke-width="4"/><path d="M54 66c-3-35 20-53 46-50 26 2 43 22 37 53-7-13-13-22-23-29-8 13-31 21-60 26z" fill="#4b281f"/><path d="M61 63c-5-19 4-38 22-48-28 3-45 26-34 58z" fill="#6a3525"/><ellipse cx="78" cy="73" rx="6" ry="8" fill="#18213b"/><ellipse cx="111" cy="73" rx="6" ry="8" fill="#18213b"/><circle cx="80" cy="70" r="2" fill="#fff"/><circle cx="113" cy="70" r="2" fill="#fff"/><path d="M86 89c6 5 13 5 19 0" fill="none" stroke="#c55d63" stroke-width="3" stroke-linecap="round"/><path d="M133 104l25-65 8 3-21 68z" fill="#dff6ff" stroke="#27405c" stroke-width="3"/><path d="M145 108l17 6 5-9-18-6z" fill="#ffc34d" stroke="#27405c" stroke-width="3"/><path d="M130 103l19 7-7 18-18-8z" fill="#ffd5ba" stroke="#17304d" stroke-width="3"/></svg>`}
function game1NodeMeta(type){
  const m={
    start:{icon:'旗',name:T('원정 입구','遠征の入口','Expedition entrance','远征入口'),desc:T('장비 없이 출발합니다. 길에서 얻은 것만 사용할 수 있어요.','装備なしで出発。道中で得た物だけ使えます。','You start with no gear and use only what you find.','无装备出发，只能使用途中获得的物品。')},
    battle:{icon:'문',name:T('몬스터 전투','モンスターバトル','Monster battle','怪物战斗'),desc:T('정답으로 몬스터를 잡으면 골드와 말빛을 얻습니다.','正解してモンスターを倒すとゴールドと言葉の光を獲得。','Defeat the monster with a correct answer for gold and Wordlight.','答对击败怪物，获得金币与语光。')},
    elite:{icon:'★',name:T('정예 몬스터','エリートモンスター','Elite monster','精英怪物'),desc:T('더 어려운 문제와 더 높은 전리품이 기다립니다.','難しい問題と豪華な戦利品が待っています。','A tougher question with better loot.','更难的题目与更丰厚的战利品。')},
    camp:{icon:'♥',name:T('야영지','野営地','Camp','营地'),desc:T('집중력을 1 회복합니다.','集中力を1回復します。','Restore 1 focus.','恢复1点专注力。')},
    treasure:{icon:'▣',name:T('보물상자','宝箱','Treasure chest','宝箱'),desc:T('골드·말빛 재화·장비 중 하나를 발견합니다.','ゴールド・言葉の光・装備のいずれかを発見。','Find gold, Wordlight currency, or gear.','发现金币、语光货币或装备。')},
    shop:{icon:'상',name:T('떠돌이 상점','旅商人の店','Wandering shop','流浪商店'),desc:T('이 칸에서만 3개의 판매 목록을 열 수 있습니다.','このマスでのみ3つの商品を購入できます。','Only this space opens a three-item shop.','仅在此格开启三件商品的商店。')},
    trap:{icon:'!',name:T('숨은 함정','隠し罠','Hidden trap','隐藏陷阱'),desc:T('집중력이나 골드를 잃을 수 있습니다.','集中力やゴールドを失うことがあります。','You may lose focus or gold.','可能失去专注力或金币。')},
    boss:{icon:game1Monster().sigil,name:game1MonsterName(),desc:T('연속 정답으로 마지막 몬스터의 HP를 깎으세요.','連続正解で最後のモンスターのHPを削ろう。','Use correct-answer combos to drain the final monster’s HP.','用连续答对削减最终怪物的HP。')}
  };return m[type]||m.battle
}
function game1Hash(value){let h=2166136261;for(const c of String(value)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function game1NodeType(depth,id,stage){
  if(depth===0)return'start';if(depth>=GAME1_TRAIL_GOAL)return'boss';
  if(depth%11===0)return'shop';if(depth%9===0)return'treasure';if(depth%7===0)return'trap';if(depth%6===0)return'camp';if(depth%5===0)return'elite';
  const n=game1Hash(`${stage}:${id}`)%12;return n===0?'treasure':n===1?'trap':'battle'
}
function game1BuildTrail(stage){
  const nodes=[],byId={},main=[];
  for(let depth=0;depth<=GAME1_TRAIL_GOAL;depth++){
    const id='m'+depth,jitter=(game1Hash(`${stage}:x:${depth}`)%13)-6,x=Math.max(18,Math.min(82,50+Math.sin((depth+stage)*1.37)*21+jitter)),y=4+depth/GAME1_TRAIL_GOAL*92,node={id,depth,x:Number(x.toFixed(1)),y:Number(y.toFixed(1)),type:game1NodeType(depth,id,stage),next:[]};nodes.push(node);byId[id]=node;main.push(node)
  }
  for(let depth=0;depth<GAME1_TRAIL_GOAL;depth++)main[depth].next=['m'+(depth+1)];
  const forks=[{start:3,end:8,side:-1},{start:10,end:15,side:1},{start:17,end:23,side:-1},{start:25,end:31,side:1}];
  forks.forEach((fork,index)=>{
    let prev=main[fork.start],first=null;
    for(let depth=fork.start+1;depth<fork.end;depth++){
      const id=`f${index}_${depth}`,base=main[depth],spread=25+((depth+index)%3)*4,x=Math.max(8,Math.min(92,base.x+fork.side*spread)),node={id,depth,x:Number(x.toFixed(1)),y:base.y,type:game1NodeType(depth,id,stage),next:[]};nodes.push(node);byId[id]=node;if(!first)first=id;prev.next=[id];prev=node
    }
    prev.next=['m'+fork.end];main[fork.start].next=['m'+(fork.start+1),first]
  });
  return nodes
}
function game1MapNode(id=Q?.currentNode){return (Q?.map||[]).find(x=>x.id===id)||null}
function game1TrailNode(id=Q?.currentNode){return game1MapNode(id)?.type||'battle'}
function game1VisibleNode(node){const current=game1MapNode(),e=game1Effects(),radius=1+(Number(e.reveal)||0);return !!Q.discovered?.[node.id]||node.depth<=Number(current?.depth||0)+radius}
function game1TrailMap(){
  const visible=(Q.map||[]).filter(game1VisibleNode),visibleIds=new Set(visible.map(x=>x.id)),lines=[];
  for(const node of visible)for(const nextId of node.next||[]){const to=game1MapNode(nextId);if(to&&visibleIds.has(nextId))lines.push(`<line x1="${node.x}" y1="${node.y}" x2="${to.x}" y2="${to.y}"></line>`)}
  const nodes=visible.map(node=>{const m=game1NodeMeta(node.type),current=node.id===Q.currentNode,passed=!!Q.discovered?.[node.id]&&!current,boss=node.type==='boss',choice=Array.isArray(Q.pendingChoices)&&Q.pendingChoices.includes(node.id),hiddenTrap=node.type==='trap'&&!Q.discovered?.[node.id]&&!game1Effects().showTraps,tilt=(game1Hash(node.id)%21)-10,scale=[.9,1.02,.96,1.07][game1Hash(node.id)%4];return `<button class="t1TrailNode ${passed?'passed':''} ${current?'current':''} ${boss?'boss':''} ${choice?'path-choice':''}" style="left:${node.x}%;top:${node.y}%;--node-tilt:${tilt}deg;--node-scale:${scale}" ${choice?`onclick="t1ChooseTrailPath('${node.id}')"`:''} ${choice?'':'disabled'} title="${E(hiddenTrap?T('알 수 없는 길','未知の道','Unknown path','未知道路'):m.name)}"><span>${hiddenTrap?'?':m.icon}</span><small>${node.depth}</small></button>`}).join('');
  const current=game1MapNode(),fogTop=Math.min(100,(current?.y||4)+10+(Number(game1Effects().reveal)||0)*5);
  return `<svg class="t1TrailPath" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${lines.join('')}</svg>${nodes}<div class="t1TrailFog" style="top:${fogTop}%"></div>`
}
function game1Focus(){return Array.from({length:Number(Q.maxFocus)||3},(_,i)=>i<(Number(Q.focus)||0)?'♥':'♡').join('')}
function game1CombatState(){const hp=Math.max(0,Number(Q.bossHp)||0),max=Math.max(1,Number(Q.bossMax)||4),pct=Math.round(hp/max*100);return{hp,max,pct,state:hp===0?'dead':pct<=35?'critical':pct<=70?'hurt':'fresh'}}
function game1MonsterMarkup(state='fresh',scope='',stage=Q?.gameStage||game1Profile().selected){
  const m=game1Monster(stage),asset=m.art&&typeof m.art==='object'?(m.art[state]||m.art.base):m.art,src=asset||mascot(state);
  return `<div class="t1MonsterAvatar ${scope}" style="--monster-accent:${m.accent};--monster-hue:${m.hue}deg"><span class="t1MonsterSigil">${m.sigil}</span><img class="tqGameMonster" src="${E(src)}" alt="${E(game1MonsterName(stage))}"></div>`
}
function game1DiceMarkup(value,rolling=false){const faces=['','⚀','⚁','⚂','⚃','⚄','⚅'],shown=rolling?'🎲':faces[value]||'🎲',label=rolling?T('주사위 굴리는 중','サイコロを振っています','Rolling dice','正在掷骰子'):value?T(`${value}이 나옴`,`${value}が出ました`,`Rolled ${value}`,`掷出${value}`):T('주사위','サイコロ','Dice','骰子');return `<span class="t1TrailDice ${rolling?'rolling':''}" aria-label="${label}"><i>${shown}</i></span>`}
function game1Weighted(entries){let total=entries.reduce((n,x)=>n+Math.max(0,Number(x.weight)||0),0),roll=Math.random()*total;for(const x of entries){roll-=Math.max(0,Number(x.weight)||0);if(roll<=0)return x}return entries[entries.length-1]}
function game1RollItem(){const luck=Number(game1Effects().luck)||0,rarities=Object.entries(GAME1_RARITIES).map(([id,x])=>({id,weight:x.weight*(id==='rare'?1+luck:id==='epic'||id==='legendary'?1+luck*1.5:1)})),rarity=game1Weighted(rarities).id,pool=GAME1_ITEMS.filter(x=>x.rarity===rarity);return game1Weighted(pool.map(x=>({...x,weight:x.weight||10})))}
function game1RarityRank(r){return ['common','uncommon','rare','epic','legendary'].indexOf(r)}
function game1AcquireItem(item,source='treasure'){
  if(!item)return null;Q.inventory=Array.isArray(Q.inventory)?Q.inventory:[];Q.equipped=Q.equipped||{};
  if(Q.inventory.includes(item.id)){const gain=2+game1RarityRank(item.rarity);Q.essence=(Number(Q.essence)||0)+gain;return{duplicate:true,gain,item}}
  const oldId=Q.equipped[item.slot],old=game1Item(oldId),beforeMax=3+(Number(game1Effects().maxFocus)||0);Q.inventory.push(item.id);
  if(!old||game1RarityRank(item.rarity)>game1RarityRank(old.rarity))Q.equipped[item.slot]=item.id;
  const afterMax=3+(Number(game1Effects().maxFocus)||0);if(afterMax>beforeMax){Q.maxFocus=afterMax;Q.focus=Math.min(afterMax,(Number(Q.focus)||0)+(afterMax-beforeMax))}
  return{item,equipped:Q.equipped[item.slot]===item.id,source}
}
function game1SyncRun(){const p=game1Profile(Q?.examLevel);if(!Q||Q.mode!=='game'||!p)return;p.run={alive:Number(Q.focus)>0,examLevel:Number(Q.examLevel)||1,gold:Math.max(0,Number(Q.gold)||0),essence:Math.max(0,Number(Q.essence)||0),inventory:[...(Q.inventory||[])],equipped:{...(Q.equipped||{})}};saveGame1()}
function game1Treasure(){
  const roll=Math.random();if(roll<.42){const amount=18+Math.floor(Math.random()*18)+Number(Q.gameStage)*3;Q.gold=(Number(Q.gold)||0)+amount;Q.event=T(`보물상자에서 골드 ${amount} 획득!`,`宝箱から${amount}ゴールド獲得！`,`Found ${amount} gold in the chest!`,`从宝箱获得${amount}金币！`)}
  else if(roll<.64){const amount=2+Math.floor(Math.random()*4);Q.essence=(Number(Q.essence)||0)+amount;Q.event=T(`말빛 재화 ${amount}개 획득!`,`言葉の光を${amount}個獲得！`,`Found ${amount} Wordlight currency!`,`获得${amount}枚语光货币！`)}
  else{const loot=game1AcquireItem(game1RollItem(),'treasure'),item=loot.item;Q.event=loot.duplicate?T(`${game1ItemName(item.id)} 중복 발견 · 말빛 ${loot.gain}로 변환!`,`${game1ItemName(item.id)}が重複・言葉の光${loot.gain}に変換！`,`Duplicate ${game1ItemName(item.id)} converted to ${loot.gain} Wordlight!`,`重复的${game1ItemName(item.id)}转化为${loot.gain}语光！`):T(`${game1RarityName(item.rarity)} 장비 · ${game1ItemName(item.id)} 획득!`,`${game1RarityName(item.rarity)}装備・${game1ItemName(item.id)}獲得！`,`Found ${game1RarityName(item.rarity)} gear: ${game1ItemName(item.id)}!`,`获得${game1RarityName(item.rarity)}装备：${game1ItemName(item.id)}！`)}
  game1SyncRun()
}
function game1Trap(){
  const e=game1Effects();if(e.trapGuard&&!Q.trapGuardUsed){Q.trapGuardUsed=true;Q.event=T('함정막이 장화가 피해를 막았습니다!','罠よけブーツが被害を防ぎました！','Trapguard Boots blocked the trap!','防陷阱靴抵挡了伤害！');return game1SyncRun()}
  if(Math.random()<.55){Q.focus=Math.max(0,(Number(Q.focus)||0)-1);Q.event=T('숨은 함정! 집중력 1을 잃었습니다.','隠し罠！集中力を1失いました。','Hidden trap! Lost 1 focus.','隐藏陷阱！失去1点专注力。')}
  else{const loss=Math.min(Number(Q.gold)||0,10+Math.floor(Math.random()*16));Q.gold=Math.max(0,(Number(Q.gold)||0)-loss);Q.event=T(`도둑 함정! 골드 ${loss}를 잃었습니다.`,`盗賊の罠！${loss}ゴールド失いました。`,`Thief trap! Lost ${loss} gold.`,`盗贼陷阱！失去${loss}金币。`)}game1SyncRun()
}
function game1MakeShop(){
  const stock=[],seen=new Set(),discount=Number(game1Effects().discount)||0,add=item=>{if(!item||seen.has(item.id))return;seen.add(item.id);stock.push({id:item.id,price:Math.max(12,Math.round((item.price+Number(Q.gameStage)*4)*(1-discount))),sold:false})};let tries=0;while(stock.length<3&&tries++<60)add(game1RollItem());for(const item of GAME1_ITEMS)if(stock.length<3)add(item);return stock
}
function game1ProcessLanding(){
  const at=game1MapNode();if(!at)return;Q.pos=at.depth;Q.node=at.type;Q.pendingChoices=[];Q.event='';
  if(at.type==='camp'){if(Number(Q.focus)<Number(Q.maxFocus)){Q.focus++;Q.event=T('야영지에서 집중력 1 회복!','野営地で集中力を1回復！','Restored 1 focus at camp!','在营地恢复1点专注力！')}else Q.event=T('집중력이 이미 가득합니다.','集中力は満タンです。','Focus is already full.','专注力已满。')}
  if(at.type==='treasure')game1Treasure();if(at.type==='trap')game1Trap();if(at.type==='shop'&&!Array.isArray(Q.shopStock))Q.shopStock=game1MakeShop();game1SyncRun()
}
function game1ContinueMovement(targetId=null){
  if(targetId){if(!Q.pendingChoices?.includes(targetId))return;Q.currentNode=targetId;Q.discovered[targetId]=1;Q.moveRemaining=Math.max(0,(Number(Q.moveRemaining)||0)-1);Q.pendingChoices=[]}
  while(Number(Q.moveRemaining)>0){const at=game1MapNode();if(!at||at.type==='boss'||!at.next?.length){Q.moveRemaining=0;break}if(at.next.length>1){Q.pendingChoices=[...at.next];Q.event=T('갈래길입니다. 이동할 방향을 선택하세요.','分かれ道です。進む方向を選んでください。','A fork in the road — choose your path.','前方是岔路，请选择方向。');saveQ();return render()}Q.currentNode=at.next[0];Q.discovered[Q.currentNode]=1;Q.moveRemaining--}
  game1ProcessLanding();saveQ();render()
}
function game1ResolveRoll(){
  restore();if(Q?.mode!=='game'||!Q.rolling)return;stopRollTimer();Q.rolling=false;Q.roll=Math.max(1,Math.min(6,Number(Q.rollPending)||1));Q.rollPending=null;Q.rollDue=null;Q.rolls=(Number(Q.rolls)||0)+1;Q.moveRemaining=Q.roll;Q.event='';game1ContinueMovement()
}
function game1ScheduleRoll(){if(!Q?.rolling)return;stopRollTimer();rollTimer=setTimeout(game1ResolveRoll,Math.max(0,(Number(Q.rollDue)||Date.now())-Date.now()))}
