window.t1ResumeGame=()=>{restore();if(Q?.mode==='game'&&Q.phase==='battle'&&!Q.locked){const remain=Math.max(1,Number(Q.pausedTime)||game1QuestionLimit());Q.questionTimeLimit=Math.max(remain,Number(Q.questionTimeLimit)||remain);Q.questionDeadline=Date.now()+remain*1000;Q.pausedTime=null;saveQ()}open('t1quiz')};
