    if(Q.i>=Q.ids.length){Q.ids=shuffle(game1QuestionIds(Q.gameStage,Q.examLevel));Q.i=0;Q.answers={}}const q=cur();if(q)delete Q.answers[q.id];Q.phase='battle';Q.locked=false;Q.hiddenChoices=[];Q.last=null;game1SetQuestionDeadline();saveQ();return render()
