try{
  const saved=JSON.parse(localStorage.getItem(SHORTS_KEY)||'null');
  if(saved?.schema===2&&saved.levels){SH={...SH,...saved,levels:{1:{...blankShorts(),...(saved.levels[1]||saved.levels['1'])},2:{...blankShorts(),...(saved.levels[2]||saved.levels['2'])}}}}
  else if(saved){SH.daily=saved.daily||{};SH.levels[2]={...blankShorts(),index:saved.index,total:saved.total,score:saved.score,streak:saved.streak}}
}catch(e){}
SH.daily=SH.daily&&typeof SH.daily==='object'?SH.daily:{};
function shortState(examLevel=SH.activeLevel||level()){
  const lv=Number(examLevel)===1?1:2,deck=shortsDeck(lv);SH.levels=SH.levels||{};SH.levels[lv]={...blankShorts(),...(SH.levels[lv]||SH.levels[String(lv)])};
  const p=SH.levels[lv];p.index=Math.max(0,Number(p.index)||0)%Math.max(1,deck.length);return p
}
function saveShorts(){try{localStorage.setItem(SHORTS_KEY,JSON.stringify(SH))}catch(e){}}
function dayKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function markHomeActivity(){const key=dayKey();SH.daily[key]=SH.daily[key]||{total:0,score:0};SH.daily[key].total=Math.min(99,(Number(SH.daily[key].total)||0)+1);saveShorts()}
function shortsStats(examLevel=level()){
  const p=shortState(examLevel);
  const now=new Date(),today=dayKey(now),monday=new Date(now),dow=(now.getDay()+6)%7;
  monday.setHours(0,0,0,0);monday.setDate(now.getDate()-dow);
  const week=Array.from({length:7},(_,i)=>{const d=new Date(monday);d.setDate(monday.getDate()+i);const key=dayKey(d);return{key,on:!!Number(SH.daily[key]?.total)}});
  let dayStreak=0,d=new Date(now);if(!Number(SH.daily[today]?.total))d.setDate(d.getDate()-1);
  while(Number(SH.daily[dayKey(d)]?.total)){dayStreak++;d.setDate(d.getDate()-1)}
  const total=Number(p.total)||0,score=Number(p.score)||0;
  return {week,weekCount:week.filter(x=>x.on).length,dayStreak,total,score,accuracy:total?Math.round(score/total*100):0};
}
function shortsOptions(index,examLevel=SH.activeLevel||level()){
  const lv=Number(examLevel)===1?1:2,deck=shortsDeck(lv),target=deck[Math.max(0,Number(index)||0)%deck.length];
  const pool=deck.filter(x=>x!==target&&x.type===target.type),start=((Number(index)||0)*5+lv)%pool.length;
  const items=Array.from({length:3},(_,i)=>pool[(start+i)%pool.length]),correct=((Number(index)||0)*3+lv)%4;
  items.splice(correct,0,target);return {items,correct,target,level:lv};
}
function shortType(type){return type==='grammar'?T('문법','文法','Grammar','语法'):type==='idiom'?T('숙어','慣用表現','Idiom','惯用语'):type==='expression'?T('표현','表現','Expression','表达'):T('단어','単語','Word','单词')}
function syncStatsNav(){
  const b=document.getElementById('nav_stats')||document.getElementById('nav_speaking');if(!b)return;
  b.id='nav_stats';b.onclick=()=>setView('stats');b.innerHTML=`<b>▥</b><span>${T('통계','統計','Stats','统计')}</span>`;
  const subtitle=document.querySelector('.top .title small');if(subtitle)subtitle.textContent='TOPIK I · II · SHORTS · RANDOM PRACTICE';
}
syncStatsNav();
window.startShorts=()=>{SH.activeLevel=level();const p=shortState();p.selected=null;p.locked=false;saveShorts();open('shorts')};
window.pickShorts=i=>{const p=shortState();if(p.locked)return;const next=Number(i);if(p.selected===next)return checkShorts();p.selected=next;saveShorts();render()};
window.checkShorts=()=>{
  const p=shortState();if(p.locked||p.selected==null)return;
  const {correct}=shortsOptions(p.index),ok=p.selected===correct,today=dayKey();
  p.locked=true;p.total=(Number(p.total)||0)+1;p.score=(Number(p.score)||0)+(ok?1:0);p.streak=ok?(Number(p.streak)||0)+1:0;
  SH.daily=SH.daily||{};SH.daily[today]=SH.daily[today]||{total:0,score:0};SH.daily[today].total++;if(ok)SH.daily[today].score++;
  saveShorts();render();
};
window.nextShorts=()=>{
  const p=shortState(),deck=shortsDeck(SH.activeLevel);let next=p.index;while(deck.length>1&&next===p.index)next=Math.floor(Math.random()*deck.length);
  p.index=next;p.selected=null;p.locked=false;saveShorts();render();
};
function bindShortsSwipe(){
  const card=document.querySelector('.shortsCard');if(!card)return;let startY=0;
  card.addEventListener('touchstart',e=>{startY=e.changedTouches[0]?.clientY||0},{passive:true});
  card.addEventListener('touchend',e=>{const end=e.changedTouches[0]?.clientY||0;if(shortState().locked&&startY-end>65)window.nextShorts()},{passive:true});
}
function renderShorts(sc){
  navActive('home');const lv=Number(SH.activeLevel)===1?1:2,p=shortState(lv),deck=shortsDeck(lv),item=deck[p.index],set=shortsOptions(p.index,lv),stats=shortsStats(lv),answer=item.meaning[S.lang]||item.meaning.ko;
  sc.className='screen tqShortsScreen';
  const choices=set.items.map((x,i)=>{
    let cls='shortsChoice';if(p.selected===i)cls+=' selected';if(p.locked&&i===set.correct)cls+=' correct';if(p.locked&&p.selected===i&&i!==set.correct)cls+=' wrong';
    return `<button class="${cls}" onclick="pickShorts(${i})" ${p.locked?'disabled':''}><i>${i+1}</i><span>${E(x.meaning[S.lang]||x.meaning.ko)}</span></button>`;
  }).join('');
  const ok=p.locked&&p.selected===set.correct;
  const feedback=p.locked?`<div class="shortsFeedback ${ok?'good':'bad'}"><b>${ok?T('정답이에요!','正解です！','Correct!','回答正确！'):T('한 번 더 기억해요','もう一度覚えましょう','Remember this one','再记一次')}</b><p>${E(item.term)} = ${E(answer)}</p><small>${T('예문','例文','Example','例句')}: ${E(item.example)}</small></div>`:'';
  sc.innerHTML=`<div class="shortsTop"><button onclick="setView('home')">‹</button><b>${T('숏츠 모드','ショーツモード','Shorts Mode','短题模式')}</b><span>🔥 ${Number(p.streak)||0}</span></div><div class="shortsProgress"><i style="width:${Math.max(8,(stats.total%10+1)*10)}%"></i></div><article class="shortsCard"><span class="shortsType">${shortType(item.type)}</span><span class="shortsLevel">TOPIK ${lv===1?'I':'II'}</span><div class="shortsWord">${E(item.term)}</div><div class="shortsInstruction">${T('한국어 표현을 보고 내 언어의 가장 가까운 뜻을 고르세요.','韓国語の表現を見て、自分の言語で最も近い意味を選んでください。','Read the Korean expression and choose its closest equivalent in your language.','阅读韩语表达，选择你语言中最接近的对应意思。')}</div><div class="shortsChoices">${choices}</div>${feedback}<div class="shortsAction">${p.locked?`<button onclick="nextShorts()">${T('다음 카드','次のカード','Next card','下一张')} ↑</button><div class="shortsSwipe">${T('위로 넘겨도 다음 문제로 이동해요','上にスワイプしても次へ進めます','Swipe up for the next card','也可以向上滑动进入下一题')}</div>`:`<div class="doubleTapHint">${T('한 번 탭해 선택 · 같은 답을 다시 탭하면 즉시 제출','1回タップで選択・同じ答えをもう一度タップすると提出','Tap once to select · tap the same answer again to submit','点一次选择 · 再点同一答案立即提交')}</div>`}</div></article>`;
  setTimeout(bindShortsSwipe,0);
}
function statsPage(sc){
  navActive('stats');const stats=shortsStats(level()),vocab=Array.isArray(S.vocab)?S.vocab.length:0;
  let reviews=0;try{reviews=Object.keys(S.realAnswers?.listen||{}).length+Object.keys(S.realAnswers?.read||{}).length}catch(e){}
  sc.className='screen tqStatsScreen';
  sc.innerHTML=`<div class="tqStatsHeader"><h1>${T('학습 통계','学習統計','Learning stats','学习统计')}</h1><button onclick="event.stopPropagation();flagMenu()">${LANGS[S.lang].flag}</button></div><section class="tqStatsHero"><small>${T('쇼츠 정답률','ショーツ正答率','SHORTS ACCURACY','短题正确率')}</small><strong>${stats.accuracy}%</strong><p>${T('짧게 공부한 기록도 꾸준히 쌓여요.','短い学習も続ければ力になります。','Every short session adds up.','每次短学习都会积累。')}</p></section><div class="tqStatsGrid"><div><b>${stats.total}</b><small>${T('푼 문제','解いた問題','Answered','已答题')}</small></div><div><b>${stats.weekCount}/7</b><small>${T('이번 주','今週','This week','本周')}</small></div><div><b>${stats.dayStreak}</b><small>${T('연속 학습일','連続学習日','Day streak','连续天数')}</small></div></div><div class="tqStatsMode"><i>⚡</i><div><b>${T('쇼츠 학습','ショーツ学習','Shorts practice','短题学习')}</b><small>${T(`정답 ${stats.score}개`,`正解 ${stats.score}問`,`${stats.score} correct`,`${stats.score}题正确`)}</small></div></div><div class="tqStatsMode"><i>▣</i><div><b>${T('단어장','単語帳','Vocabulary','单词本')}</b><small>${T(`${vocab}개 저장`,`${vocab}語を保存`,`${vocab} saved`,`${vocab}个已保存`)}</small></div></div><div class="tqStatsMode"><i>↻</i><div><b>${T('실전 답안','実戦答案','Exam answers','实战答题')}</b><small>${T(`${reviews}문항 기록`,`${reviews}問を記録`,`${reviews} recorded`,`${reviews}题记录`)}</small></div></div>`;
}
